<?php

namespace WConvert\Template;

defined('ABSPATH') || exit;

/**
 * The catalogue revision of each design a ZIP bundles (ADR 0156).
 *
 * Bundled designs are also published as downloadable objects, and across
 * bundled, installed and remote copies the highest revision wins. So a
 * bundled design has to say which revision it is. That number lives here,
 * generated by the publisher's revision registry
 * (`tools/design-library/publishing/revisions.json`), rather than inside each
 * design file — a key in the design would change the bytes every review
 * approval is pinned to.
 *
 * An id the file does not list is revision 1.
 */
final class BundledRevisions
{
    /** @return array<string, int> */
    public static function read(string $file): array
    {
        $decoded = JsonFile::read($file);
        $revisions = [];
        foreach (is_array($decoded['designs'] ?? null) ? $decoded['designs'] : [] as $id => $revision) {
            if (is_string($id) && is_int($revision) && $revision >= 1) $revisions[$id] = $revision;
        }
        return $revisions;
    }

    /**
     * @param list<array<string, mixed>> $entries
     * @param array<string, int> $revisions
     * @return list<array<string, mixed>>
     */
    public static function stamp(array $entries, array $revisions): array
    {
        foreach ($entries as &$entry) {
            $id = is_string($entry['id'] ?? null) ? $entry['id'] : '';
            $entry['revision'] = $revisions[$id] ?? 1;
            $entry['design_key'] = 'registered:' . $id;
        }
        return $entries;
    }
}
